counts = {}
for v in votes:
    counts[v] = counts.get(v, 0) + 1
print(max(counts, key=counts.get))

def is_spam(msg):
    spam_words = {"free", "win", "prize"}
    score = sum(1 for w in msg.lower().split() if w in spam_words)
    return score >= 2

print(is_spam("Win a FREE trip"))
print(is_spam("See you at school"))
